import json
import os
import xlwt
import pandas as pd


def task_func(json_str, filename, sheet_name="sheet1"):
    if not isinstance(json_str, (str, bytes, bytearray)):
        raise TypeError("json_str must be a string, bytes, or bytearray")

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ValueError("json_str is not valid JSON") from exc

    if isinstance(data, list):
        df = pd.DataFrame(data)
    elif isinstance(data, dict):
        df = pd.DataFrame([data])
    else:
        df = pd.DataFrame({"value": [data]})

    workbook = xlwt.Workbook()
    worksheet = workbook.add_sheet(sheet_name)

    for col_index, column_name in enumerate(df.columns):
        worksheet.write(0, col_index, str(column_name))

    for row_index, row in enumerate(df.itertuples(index=False, name=None), start=1):
        for col_index, value in enumerate(row):
            if isinstance(value, (dict, list)):
                value = json.dumps(value)
            elif pd.isna(value):
                value = ""
            worksheet.write(row_index, col_index, value)

    workbook.save(filename)
    return os.path.abspath(filename)
